def extract(text):
    result={}
    matches=list(re.finditer(r'^#{3,4} PT[‑-](\d+) · (.+)$',text,re.M))
    for m in matches:
        end=re.search(r'^#{1,4} ',text[m.end():],re.M)
        body=text[m.end():m.end()+end.start() if end else len(text)].strip().removesuffix('---').strip()
        result[int(m[1])]=(m[2],body)
    return result
